{
  "questions": [
    {
      "type": "compare_contrast",
      "parts": [
        "L01/P04",
        "L01/P07"
      ],
      "question": "The lecture introduces the reality-virtuality continuum, which spans from a completely real environment to a completely virtual environment. Compare and contrast Augmented Reality (AR), Mixed Reality (MR), and Virtual Reality (VR) based on where they are positioned on this spectrum and what defines them at those points.",
      "reference_answer": "The reality-virtuality continuum acts as a spectrum, ranging from the purely real world to the completely virtual world. Virtual Reality (VR) represents one extreme, where reality is completely replaced by virtuality. Augmented Reality (AR) is positioned toward the real end of the continuum, as it augments the real world with digital content. Mixed Reality (MR) broadly encompasses the entire space between the two extremes. MR involves different degrees of augmentation—meaning it includes both AR and Augmented Virtuality—and is characterized by the integration of real and virtual content.",
      "key_points": [
        {
          "text": "VR represents the extreme end of complete virtuality.",
          "keywords": [
            "Virtual environment",
            "completely virtual"
          ],
          "sentence_ids": [
            118,
            119
          ]
        },
        {
          "text": "AR augments the real world using digital or virtual content.",
          "keywords": [
            "augmenting the real world",
            "digital content"
          ],
          "sentence_ids": [
            120,
            122
          ]
        },
        {
          "text": "MR is the broad term for the entire space between the two extremes.",
          "keywords": [
            "entire space between",
            "purely virtual and purely real"
          ],
          "sentence_ids": [
            126,
            130
          ]
        }
      ]
    },
    {
      "type": "explain_mechanism",
      "parts": [
        "L01/P05",
        "L01/P06"
      ],
      "question": "The XR field is experiencing massive growth, driven partly by the concept of the Metaverse. Explain how the shift in human-computer interaction described by the Metaverse is influencing the overall market and the future skills required in the XR industry.",
      "reference_answer": "The Metaverse is stimulating growth because it is reimagining human interaction, moving beyond the traditional flat, 2D screen interactions. Instead, it envisions an all-around 3D environment where users interact using a 'natural way of interaction,' similar to how they act in the real world. This shift fundamentally changes human-computer interaction, leading to huge investment in the field. Because of this exponential market growth, particularly in hardware and software, there will be a significant demand for knowledgeable and skilled manpower.",
      "key_points": [
        {
          "text": "The Metaverse aims to reimagine human interaction into a 3D environment.",
          "keywords": [
            "reimagine the way humans interact",
            "all-around 3D world"
          ],
          "sentence_ids": [
            176,
            179
          ]
        },
        {
          "text": "Interaction is shifting from flat 2D screens to natural, 3D methods.",
          "keywords": [
            "flat type of interactions",
            "natural way of interaction"
          ],
          "sentence_ids": [
            177,
            179
          ]
        },
        {
          "text": "This growth creates a high demand for skilled labor in both hardware and software.",
          "keywords": [
            "significant demand for skilled manpower",
            "growth potential will be there"
          ],
          "sentence_ids": [
            186,
            184
          ]
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "type": "compare_contrast",
      "parts": [
        "L02/P03",
        "L02/P04",
        "L02/P05"
      ],
      "question": "Compare and contrast the three main categories of VR systems—non-immersive, semi-immersive, and fully immersive—by explaining how each category differs in its degree of immersion and required hardware.",
      "reference_answer": "VR systems are categorized based on the varying degrees of immersion they provide. Non-immersive VR is a virtual experience obtained through a computer where the environment does not directly interact with the user, relying on psychological engagement despite open senses. Semi-immersive systems occupy the middle ground, allowing partial immersion by blocking only specific sensory organs, often utilizing a VR headset. Fully immersive systems represent the highest level, completely blocking all the user's senses and replacing natural reality with virtual realism, which requires the most complex and costly gear, such as suits and body connectors.",
      "key_points": [
        {
          "text": "Non-immersive relies on psychological engagement with open senses.",
          "keywords": [
            "psychological engagement",
            "open senses"
          ],
          "sentence_ids": [
            119,
            120
          ]
        },
        {
          "text": "Semi-immersive systems allow partial immersion by blocking only some senses.",
          "keywords": [
            "partial immersion",
            "blocking some of the sensory organs"
          ],
          "sentence_ids": [
            131,
            134
          ]
        },
        {
          "text": "Fully immersive systems completely block all senses to replace reality.",
          "keywords": [
            "completely blocking the user's senses",
            "virtual realism"
          ],
          "sentence_ids": [
            144,
            145,
            147
          ]
        }
      ]
    },
    {
      "type": "explain_mechanism",
      "parts": [
        "L02/P02",
        "L02/P05"
      ],
      "question": "Explain how the requirements of a specific application domain, such as specialized military training, dictate the necessity of a certain level of VR immersion.",
      "reference_answer": "The required level of immersion is tied to the application's need for realism. For critical areas like specialized military training, simulations must be fully immersive because they must allow personnel to practice real-world scenarios while the senses are blocked to ensure total presence. Conversely, applications like virtual tours often utilize semi-immersive systems, such as a VR headset, which is considered more cost-effective and provides partial immersion while the user remains free to sense the real world.",
      "key_points": [
        {
          "text": "Specialized military training requires high immersion for realism.",
          "keywords": [
            "specialized military training",
            "simulated in a virtual world"
          ],
          "sentence_ids": [
            67,
            68
          ]
        },
        {
          "text": "Fully immersive systems ensure total presence by blocking all senses.",
          "keywords": [
            "completely blocking the user's ability to sense the real world",
            "virtual world"
          ],
          "sentence_ids": [
            144,
            145
          ]
        },
        {
          "text": "Semi-immersive systems are often used in commercial applications for cost-effectiveness.",
          "keywords": [
            "semi-immersive systems",
            "cost-effective"
          ],
          "sentence_ids": [
            139,
            166
          ]
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "type": "compare_contrast",
      "parts": [
        "L03/P05",
        "L03/P01"
      ],
      "question": "A new student is confused about the fundamental differences between Virtual Reality (VR) and Augmented Reality (AR). Based on the lecture, how do these two technologies fundamentally differ in terms of their primary focus (experience vs. content) and how are their systems categorized?",
      "reference_answer": "VR systems are primarily categorized by the user's psychological experience, defining categories such as non-immersive, semi-immersive, and fully immersive. In contrast, AR applications prioritize the augmentation of real-world content with digital content, meaning the immersive experience is not mandatory. Furthermore, AR systems are categorized based on the technology used, specifically into marker-based and markerless applications, rather than psychological factors.",
      "key_points": [
        {
          "text": "VR is categorized by the user's psychological experience.",
          "keywords": [
            "psychological experience",
            "VR systems"
          ],
          "sentence_ids": [
            106,
            107
          ]
        },
        {
          "text": "AR focuses on augmenting real-world content, not just immersion.",
          "keywords": [
            "augmentation of real-world content",
            "not mandatory"
          ],
          "sentence_ids": [
            14,
            123
          ]
        },
        {
          "text": "AR systems are categorized by the technology used.",
          "keywords": [
            "technology used",
            "marker-based and markerless"
          ],
          "sentence_ids": [
            110,
            61
          ]
        }
      ]
    },
    {
      "type": "explain_mechanism",
      "parts": [
        "L03/P04"
      ],
      "question": "Markerless AR is described as highly versatile. Explain the distinct technical mechanisms used by the three major subtypes of markerless AR applications: location-based, superimposition-based, and projection-based.",
      "reference_answer": "Markerless applications rely on computer vision techniques because they do not require pre-placed markers. Location-based AR uses sensors, such as GPS, to detect the user's geographical location and augment content based on that specific reference point. Superimposition-based systems utilize computer vision to recognize physical objects in the real world, allowing digital content to be placed based on that recognition. Finally, projection-based AR systems employ light projectors to cast digital graphics or characters onto objects, surfaces, or space.",
      "key_points": [
        {
          "text": "Markerless systems rely on computer vision techniques.",
          "keywords": [
            "computer vision techniques",
            "do not require markers"
          ],
          "sentence_ids": [
            78,
            80
          ]
        },
        {
          "text": "Location-based AR uses sensors (like GPS) for geographical positioning.",
          "keywords": [
            "GPS sensor",
            "detect the location"
          ],
          "sentence_ids": [
            85,
            87
          ]
        },
        {
          "text": "Superimposition systems recognize objects to guide augmentation.",
          "keywords": [
            "recognize physical objects",
            "superimposing digital content"
          ],
          "sentence_ids": [
            90,
            93
          ]
        },
        {
          "text": "Projection-based systems use light projectors to display content.",
          "keywords": [
            "use light projectors",
            "onto an object or surface"
          ],
          "sentence_ids": [
            94,
            95
          ]
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "type": "troubleshooting",
      "parts": [
        "L04/P04",
        "L04/P06",
        "L04/P05"
      ],
      "question": "You are analyzing a brand-new flight simulator game. The game displays a highly realistic cockpit (Virtual Environment is present) and allows the user to use buttons to change the altitude and turn the controls (Interaction is present). However, the user is still seated in a normal room and is only looking at a large monitor; there is no head-mounted display or sensory input blocking the real world. Based on the lecture's criteria, evaluate this system. Which characteristic is missing, and why is the system not considered true Virtual Reality?",
      "reference_answer": "Although the flight simulator possesses a virtual environment and allows for interaction through controls, it fails to meet the requirement for immersive experience. The lecture specifies that full immersion requires generating stimuli that stimulate all the user's sensory organs, which would involve blocking the user from the surrounding real world. Since the user remains in a normal room and only looks at a monitor, the system is lacking the full sensory stimulation needed for true VR classification. It meets two criteria but fails the third, making it not a VR system.",
      "key_points": [
        {
          "text": "A system must satisfy all three characteristics to be classified as VR.",
          "keywords": [
            "satisfy all three",
            "VR system"
          ],
          "sentence_ids": [
            81,
            82
          ]
        },
        {
          "text": "The system lacks immersive experience because the real world is visible.",
          "keywords": [
            "immersive experience",
            "stimulate all sensory organs"
          ],
          "sentence_ids": [
            105,
            106
          ]
        },
        {
          "text": "Immersion requires generating stimuli that stimulate all sensory organs.",
          "keywords": [
            "generating stimuli",
            "sensory organs"
          ],
          "sentence_ids": [
            103,
            104
          ]
        }
      ]
    },
    {
      "type": "compare_contrast",
      "parts": [
        "L04/P01",
        "L04/P03"
      ],
      "question": "Explain the foundational difference between 'reality' and 'virtual' as defined in the lecture. How does this core conceptual difference govern how we define an 'artificial environment' in the context of a Virtual Reality system?",
      "reference_answer": "Reality is defined as existing independently of ideas concerning it, constituting something real or actual and existing in fact. In contrast, 'virtual' means existing in essence or effect, but not in fact; it is something that is there but cannot be attributed to any factual thing. This distinction dictates that an artificial environment in a VR system must be a computer-generated scenario. While this environment may use real-world imagery (as in a virtual tour), it is ultimately defined as synthetic and not real, conforming to the definition of 'virtual' because it does not exist as a factual, physical thing.",
      "key_points": [
        {
          "text": "Reality exists independently of ideas and constitutes an actual thing.",
          "keywords": [
            "exists independently",
            "constitutes a real or actual thing"
          ],
          "sentence_ids": [
            17,
            22
          ]
        },
        {
          "text": "Virtual means existing in effect, but not in fact.",
          "keywords": [
            "essence or effect",
            "not in fact"
          ],
          "sentence_ids": [
            13,
            14
          ]
        },
        {
          "text": "An artificial environment must be computer-generated and synthetic.",
          "keywords": [
            "computer generated environment",
            "synthetic graphical view"
          ],
          "sentence_ids": [
            43,
            72
          ]
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "type": "compare_contrast",
      "parts": [
        "L09/P01",
        "L09/P03"
      ],
      "question": "Some users view reality as a standard to be matched, while others believe reality should be transcended. How do these two differing philosophical views influence the design of a VR system, and how do the concepts of representational, interaction, and experiential fidelity help mitigate the risks of the Uncanny Valley effect?",
      "reference_answer": "The design of a VR system is influenced by whether reality is seen as a gold standard for mimicry, or something that must surpass lived experience. If the goal is mimicry, the system aims to closely match sensory stimuli with psychological perception. Regardless of the philosophical approach, high realism can fall into the uncanny valley, causing the experience to deteriorate. To avoid this, designers must balance three types of fidelity: representational (matching the place's familiarity), interaction (how physical actions correspond to virtual tasks), and experiential (how closely the user's personal experience matches the creator's intended experience).",
      "key_points": [
        {
          "text": "Reality can be seen as a gold standard for mimicry.",
          "keywords": [
            "reality is the gold standard",
            "match the experience"
          ],
          "sentence_ids": [
            15,
            17,
            18
          ]
        },
        {
          "text": "Other users define reality as something that must be surpassed.",
          "keywords": [
            "surpasses lived experience",
            "beyond our lived perception"
          ],
          "sentence_ids": [
            20,
            22,
            23
          ]
        },
        {
          "text": "High realism may cause the experience to deteriorate due to the uncanny valley effect.",
          "keywords": [
            "realism may not be appearing realistic",
            "experience to deteriorate"
          ],
          "sentence_ids": [
            60,
            62,
            63
          ]
        },
        {
          "text": "The three fidelities—representational, interaction, and experiential—guide VR design.",
          "keywords": [
            "representational, interaction, and experiential fidelity",
            "guide VR design"
          ],
          "sentence_ids": [
            70,
            71,
            94
          ]
        }
      ]
    },
    {
      "type": "explain_mechanism",
      "parts": [
        "L09/P04",
        "L09/P05",
        "L09/P06"
      ],
      "question": "Since Augmented Reality is primarily a technical challenge rather than a psychological one, what three technical requirements must an AR system fulfill? Furthermore, how does the system accurately place virtual content into the real world by using the registration and tracking phases?",
      "reference_answer": "AR systems must combine the real and virtual worlds, be interactive in 3D and real time, and be registered in 3D. To achieve 3D registration, the system must determine the viewer's pose—the combination of position and orientation—relative to a real-world anchor. This determination involves two stages: first, the registration phase, which establishes the initial pose; second, the tracking phase, which continuously updates the pose based on previous known positions as the user moves.",
      "key_points": [
        {
          "text": "AR systems must combine real and virtual content, be interactive, and register in 3D.",
          "keywords": [
            "combine real and virtual worlds",
            "interactive in real time and 3D"
          ],
          "sentence_ids": [
            105,
            108
          ]
        },
        {
          "text": "The system must determine the viewer's pose relative to a real-world anchor.",
          "keywords": [
            "pose of the viewer",
            "real-world anchor"
          ],
          "sentence_ids": [
            121,
            123
          ]
        },
        {
          "text": "Registration sets the initial pose, while tracking continuously updates the pose during movement.",
          "keywords": [
            "registration phase determines the initial pose",
            "tracking updates the pose"
          ],
          "sentence_ids": [
            129,
            131,
            134
          ]
        },
        {
          "text": "The primary challenges for AR are technological, such as display and pose estimation.",
          "keywords": [
            "challenges are mostly technological",
            "pose estimation"
          ],
          "sentence_ids": [
            102,
            152
          ]
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "type": "compare_contrast",
      "parts": [
        "L07/P04",
        "L07/P05"
      ],
      "question": "Compare the driving forces and technological limitations during the Tools or Applications Phase (mid-1990s to 2007) with the drivers of the current Commercial Application Phase (post-2007).",
      "reference_answer": "During the Tools or Applications Phase, research was driven by solving technical challenges like pinpointing viewpoint tracking and building core enabling technologies such as tracking and interaction. However, these systems were often bulky due to custom hardware and tracking sensors. In contrast, the commercial phase was driven by widespread availability and consumer adoption. This growth was significantly catalyzed by consumer devices like smartphones and by crucial software tools such as ARKit and ARCore, which allowed for massive application growth and accessibility.",
      "key_points": [
        {
          "text": "The earlier phase focused on solving complex technical issues and developing core enabling technologies.",
          "keywords": [
            "key enabling technologies",
            "viewpoint tracking",
            "tracking"
          ],
          "sentence_ids": [
            104,
            80
          ]
        },
        {
          "text": "Early AR systems in the mid-1990s were technologically capable but were generally large and cumbersome.",
          "keywords": [
            "bulky due to the size",
            "custom computer hardware"
          ],
          "sentence_ids": [
            98,
            103
          ]
        },
        {
          "text": "The commercial phase was accelerated by mass market consumer technologies like smartphones.",
          "keywords": [
            "smartphone-based AR",
            "era of smartphones"
          ],
          "sentence_ids": [
            128,
            129
          ]
        },
        {
          "text": "Modern growth has been greatly stimulated by development tools like ARKit and ARCore.",
          "keywords": [
            "ARKit SDK",
            "ARCore"
          ],
          "sentence_ids": [
            133,
            134
          ]
        }
      ]
    },
    {
      "type": "explain_mechanism",
      "parts": [
        "L07/P02",
        "L07/P04"
      ],
      "question": "Explain the mechanism of how early augmented reality systems functioned and how subsequent developments replaced initial limitations.",
      "reference_answer": "The earliest AR prototype from 1968, created by Ivan Sutherland and Bob Sproull, used an optical see-through HMD combined with a ceiling-mounted mechanical tracking system for 3D registration. This mechanism allowed computer graphics to be superimposed over the pilot's real-world view. A key limitation was the tracking hardware; this mechanical tracker was eventually replaced by more advanced systems. Later developments leveraged computer vision techniques, such as Rekimoto's cyber code system and the open-source AR Toolkit, to enable real-time marker-based tracking and accurate viewpoint registration.",
      "key_points": [
        {
          "text": "Early AR utilized a CRT-based, optical see-through HMD connected to a mechanical tracker.",
          "keywords": [
            "CRT-based",
            "optical see-through head mounted display"
          ],
          "sentence_ids": [
            28,
            36
          ]
        },
        {
          "text": "The purpose of the mechanical tracking was to allow 3D registration and movement detection.",
          "keywords": [
            "3D registering",
            "ceiling-mounted mechanical tracker"
          ],
          "sentence_ids": [
            36,
            29
          ]
        },
        {
          "text": "Mechanical tracking systems were later substituted by more sophisticated methods.",
          "keywords": [
            "mechanical tracker was later replaced",
            "ultrasonic system"
          ],
          "sentence_ids": [
            33
          ]
        },
        {
          "text": "Modern advancements used computer vision to achieve real-time, marker-based tracking.",
          "keywords": [
            "computer vision tracking system",
            "real-time computer vision"
          ],
          "sentence_ids": [
            107,
            109
          ]
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "type": "compare_contrast",
      "parts": [
        "L08/P05",
        "L08/P06"
      ],
      "question": "Explain the relationship between Immersion and Presence. Why, despite both being key concerns in VR, is the overall ultimate goal of any VR system focused on Presence?",
      "reference_answer": "Immersion is an objective, measurable description of the technology's capabilities, referring to the degree to which sensory organs are activated. Conversely, Presence is a subjective psychological state where the user fails to acknowledge the technology's role and perceives the experience as reality. While Immersion aids and enhances the perception of Presence, it does not guarantee that Presence will occur, as the user can manually reject the experience. Therefore, the overarching goal of a VR system is to create a high degree of Presence, making the user unable to distinguish between the virtual and real worlds.",
      "key_points": [
        {
          "text": "Immersion is an objective description of technology's capabilities.",
          "keywords": [
            "objective",
            "measurable",
            "technology's capabilities"
          ],
          "sentence_ids": [
            133,
            159
          ]
        },
        {
          "text": "Presence is a subjective psychological state that the user experiences.",
          "keywords": [
            "subjective psychological state",
            "perception"
          ],
          "sentence_ids": [
            141,
            157
          ]
        },
        {
          "text": "Immersion aids Presence, but does not guarantee it.",
          "keywords": [
            "Immersion aids presence",
            "does not guarantee"
