        }
      ]
    },
    {
      "type": "explain_mechanism",
      "parts": [
        "L08/P03",
        "L08/P04"
      ],
      "question": "Immersion is defined by six qualitative terms. How do qualities like 'Matching,' 'Vivid quality,' and 'Interactivity' function together to make a VR experience feel fully realized?",
      "reference_answer": "Immersion is measured by six qualities. 'Matching' ensures sensory congruence, meaning a user's physical movements, such as a head turn, correspond instantly to the virtual world without delay. 'Vivid quality' relates to the energy of the stimulation within each modality, which is enhanced by factors like high resolution or varied lighting. Finally, 'Interactivity' allows the user to influence future events and make changes to the world, combining physical congruence with functional agency.",
      "key_points": [
        {
          "text": "Matching requires that physical movements correspond instantly to the virtual representation.",
          "keywords": [
            "congruence between sensory modalities",
            "instantly"
          ],
          "sentence_ids": [
            86,
            88
          ]
        },
        {
          "text": "Vivid quality refers to the energy generated to stimulate a sensory organ.",
          "keywords": [
            "quality of energy stimulated",
            "resolution, lighting, frame rate"
          ],
          "sentence_ids": [
            102,
            105
          ]
        },
        {
          "text": "Interactivity gives the user the ability to change the world and influence future events.",
          "keywords": [
            "capability of the user to make changes",
            "influence future events"
          ],
          "sentence_ids": [
            113,
            114
          ]
        }
      ]
    }
  ]
}

{
  "questions": [
    {
      "type": "compare_contrast",
      "parts": [
        "L05/P03",
        "L05/P05"
      ],
      "question": "A friend is trying to understand the fundamental differences between Virtual Reality (VR) and Augmented Reality (AR). Explain how these two technologies alter or interact with a user's perception of reality.",
      "reference_answer": "The core difference lies in how each system interacts with the physical world. Virtual Reality (VR) completely replaces a user's sense of reality, immersing them entirely in a synthetic virtual environment, and thus does not require a physical object to exist. In contrast, Augmented Reality (AR) alters the ongoing perception of the real world. AR achieves this by superimposing digital content—like information or images—over the existing physical environment. For AR to function, the physical environment it is enhancing must exist.",
      "key_points": [
        {
          "text": "VR completely replaces reality.",
          "keywords": [
            "completely replaces",
            "sense of reality"
          ],
          "sentence_ids": [
            73,
            75,
            152
          ]
        },
        {
          "text": "AR alters the ongoing perception of the real world.",
          "keywords": [
            "alters the ongoing perception",
            "real world"
          ],
          "sentence_ids": [
            70,
            74,
            152
          ]
        },
        {
          "text": "AR requires the physical environment to exist.",
          "keywords": [
            "physical existence",
            "must exist"
          ],
          "sentence_ids": [
            86,
            93
          ]
        }
      ]
    },
    {
      "type": "explain_mechanism",
      "parts": [
        "L05/P02"
      ],
      "question": "To ensure a system is correctly classified as Augmented Reality (AR), what are the essential characteristics it must satisfy? Explain why these requirements—especially 3D registration and interaction—are critical for the technology to be considered a true AR system.",
      "reference_answer": "A system is defined as AR only if four characteristics are satisfied: the real world must be enhanced with digital content; the enhancement must be registered in 3D; it must be experienced through sensory organs; and it must support user interaction. 3D registration is crucial because it ensures that the digital content is placed appropriately and seamlessly mixes with real-world objects. Furthermore, supporting interaction means the user can actively engage with the digital content within the enhanced environment, maintaining the feeling that they are present in the enhanced reality.",
      "key_points": [
        {
          "text": "AR systems must have four essential characteristics.",
          "keywords": [
            "four characteristics",
            "AR system"
          ],
          "sentence_ids": [
            53,
            67
          ]
        },
        {
          "text": "3D registration allows seamless integration with real objects.",
          "keywords": [
            "registered in 3D",
            "seamless mixing"
          ],
          "sentence_ids": [
            39,
            43
          ]
        },
        {
          "text": "Interaction allows the user to actively engage with digital content.",
          "keywords": [
            "support interaction",
            "enhanced environment"
          ],
          "sentence_ids": [
            47,
            50
